package com.curso.services;
import com.curso.cotacao.*;import com.curso.domains.*;import com.curso.domains.dtos.InvestimentoDTOs.*;import com.curso.repositories.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.List;
@Service public class CotacaoService{private final CotacaoOrchestrator orq;private final AtivoRepository ativos;private final ConsultaRepository consultas;private final UsuarioAtualService atual;public CotacaoService(CotacaoOrchestrator o,AtivoRepository a,ConsultaRepository c,UsuarioAtualService u){orq=o;ativos=a;consultas=c;atual=u;}
 @Transactional public CotacaoResponse buscar(String simbolo){Usuario u=atual.obter();CotacaoAtual c=orq.buscar(simbolo);Ativo a=ativos.findBySimboloIgnoreCase(c.simbolo()).orElseGet(()->"BRL".equals(c.moeda())?ativos.obterOuCriar(c.simbolo(),c.nome(),c.bolsa()):ativos.obterOuCriar(c.simbolo(),c.nome(),c.bolsa(),c.moeda()));Moedas.conferir(a.getMoeda(),c.moeda());consultas.save(new Consulta(null,u,a,c.preco(),c.fonte(),LocalDateTime.now()));return new CotacaoResponse(c.simbolo(),c.nome(),c.bolsa(),c.preco(),c.fonte(),c.moeda());}
 @Transactional(readOnly=true) public List<ConsultaResponse> historico(){return consultas.findByUsuarioIdOrderByConsultadoEmDesc(atual.obter().getId()).stream().map(c->new ConsultaResponse(c.getId(),c.getAtivo().getSimbolo(),c.getValor(),c.getFonte(),c.getConsultadoEm(),c.getAtivo().getMoeda())).toList();}}
